package com.gass.jobs;
import android.app.Activity;import android.content.pm.ActivityInfo;import android.graphics.Color;import android.graphics.Typeface;import android.net.Uri;import android.os.Bundle;import android.view.*;import android.widget.*;import java.net.*;import java.io.*;import java.util.*;
public class TvActivity extends Activity{
 static final int BG=0xff0a0b0e,PANEL=0xff191b21,GOLD=0xffffbe2d,WHITE=0xfff5f6fa,MUTED=0xffabb2be;static final String BASE="https://iptv-org.github.io/iptv/";
 static final String[][] SRC={{"🇹🇳 Tunisie","countries/tn"},{"🇱🇺 Luxembourg","countries/lu"},{"🇫🇷 France","countries/fr"},{"🇩🇿 Algérie","countries/dz"},{"🇲🇦 Maroc","countries/ma"},{"🌙 Monde arabe","regions/arab"},{"🌍 Monde","regions/ww"},{"📰 Actualités","categories/news"},{"⚽ Sport","categories/sports"},{"🎬 Divertissement","categories/entertainment"},{"🎵 Musique","categories/music"},{"🎓 Éducation","categories/education"}};
 LinearLayout root,list;FrameLayout frame;VideoView video;TextView status;View header,chipView,listView;ProgressBar spinner;boolean full=false;int pad,height;
 int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}TextView txt(String s,int z,int c,boolean b){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);if(b)t.setTypeface(Typeface.DEFAULT,1);return t;}
 android.graphics.drawable.GradientDrawable bg(){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(PANEL);d.setCornerRadius(dp(12));d.setStroke(dp(1),0xff3e3728);return d;}Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextColor(GOLD);b.setAllCaps(false);b.setTextSize(12);b.setBackground(bg());return b;}
 public void onCreate(Bundle b){super.onCreate(b);pad=dp(14);height=(int)((getResources().getDisplayMetrics().widthPixels-2*pad)*9f/16f);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(pad,pad,pad,pad);root.setBackgroundColor(BG);header=txt("📺  GASS-OS TV",22,GOLD,true);root.addView(header);root.addView(txt("Chaînes publiques • pays et catégories",12,MUTED,false));frame=new FrameLayout(this);frame.setBackgroundColor(Color.BLACK);video=new VideoView(this);frame.addView(video,new FrameLayout.LayoutParams(-1,-1,Gravity.CENTER));spinner=new ProgressBar(this);spinner.setVisibility(View.GONE);frame.addView(spinner,new FrameLayout.LayoutParams(dp(42),dp(42),Gravity.CENTER));video.setOnPreparedListener(p->{spinner.setVisibility(View.GONE);p.start();});video.setOnErrorListener((p,w,e)->{spinner.setVisibility(View.GONE);status.setText("Flux indisponible, hors ligne ou géo-bloqué.");return true;});video.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_UP)setFull(!full);return true;});LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,height);fp.topMargin=dp(10);root.addView(frame,fp);
 HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);LinearLayout chips=new LinearLayout(this);for(String[] s:SRC){Button b0=btn(s[0]);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(42));p.rightMargin=dp(6);chips.addView(b0,p);b0.setOnClickListener(v->load(s[1]));}hs.addView(chips);chipView=hs;LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,dp(48));hp.topMargin=dp(8);root.addView(hs,hp);status=txt("Choisissez un pays ou une catégorie.",12,MUTED,false);root.addView(status);ScrollView sv=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(1);sv.addView(list);listView=sv;root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);load("countries/tn");}
 void load(String path){status.setText("Chargement des chaînes…");list.removeAllViews();new Thread(()->{ArrayList<String[]> rows=new ArrayList<>();String error=null;try{String body=get(BASE+path+".m3u"),name=null;for(String line:body.split("\n")){line=line.trim();if(line.startsWith("#EXTINF")){int i=line.lastIndexOf(',');name=i>=0?line.substring(i+1).trim():"Chaîne";}else if(!line.isEmpty()&&!line.startsWith("#")&&name!=null){if(line.startsWith("http"))rows.add(new String[]{name,line});name=null;}}}catch(Exception e){error=e.getMessage();}final ArrayList<String[]> rr=rows;final String ee=error;runOnUiThread(()->show(rr,ee));}).start();}
 void show(ArrayList<String[]> rows,String err){list.removeAllViews();if(rows.isEmpty()){status.setText(err==null?"Aucune chaîne dans cette liste":"Réseau indisponible : "+err);return;}status.setText(rows.size()+" chaînes disponibles • touchez pour lancer");int n=0;for(String[] c:rows){if(n++>=180)break;LinearLayout card=new LinearLayout(this);card.setPadding(dp(12),dp(12),dp(12),dp(12));card.setBackground(bg());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(6);list.addView(card,p);card.addView(txt("📺  "+c[0],14,WHITE,true));card.setOnClickListener(v->play(c[0],c[1]));}}
 void play(String name,String url){status.setText("Lecture : "+name);spinner.setVisibility(View.VISIBLE);video.stopPlayback();video.setVideoURI(Uri.parse(url));}
 void setFull(boolean f){full=f;int vis=f?View.GONE:View.VISIBLE;header.setVisibility(vis);chipView.setVisibility(vis);status.setVisibility(vis);listView.setVisibility(vis);root.setPadding(f?0:pad,f?0:pad,f?0:pad,f?0:pad);ViewGroup.LayoutParams p=frame.getLayoutParams();p.height=f?ViewGroup.LayoutParams.MATCH_PARENT:height;frame.setLayoutParams(p);setRequestedOrientation(f?ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE:ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED);getWindow().getDecorView().setSystemUiVisibility(f?(View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY|View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION):0);}
 String get(String u)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setRequestProperty("User-Agent","GASS-JOBS/1.0");try(InputStream in=c.getInputStream();ByteArrayOutputStream o=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)o.write(b,0,n);return o.toString("UTF-8");}finally{c.disconnect();}}
 protected void onPause(){if(video!=null)video.pause();super.onPause();}public void onBackPressed(){if(full)setFull(false);else super.onBackPressed();}protected void onDestroy(){if(video!=null)video.stopPlayback();super.onDestroy();}
}